<script>
(function () {
  'use strict';

  var form = document.getElementById('signup');
  var status = document.getElementById('form-status');

  // ---- Domain names -------------------------------------------------------

  // Characters that would make the URL parser read something other than a host.
  var NOT_HOST = /[\s\/\\?#:@%\[\]]/;
  // One label in A-label (ASCII) form: 1–63 letters, digits or hyphens, no edge hyphen.
  var LABEL = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;
  // TLD: two or more letters (no upper cap beyond the 63-octet label limit),
  // or an A-label such as xn--p1ai (.рф).
  var TLD = /^(?:[a-z]{2,}|xn--[a-z0-9-]+)$/;

  // Checks a host name that is already in lower-case ASCII form.
  function isHostname(host) {
    if (!host || host.length > 253) return false;
    var labels = host.split('.');
    if (labels.length < 2) return false;
    for (var i = 0; i < labels.length; i++) {
      if (!LABEL.test(labels[i])) return false;
    }
    return TLD.test(labels[labels.length - 1]);
  }

  // Converts a domain (U-labels or A-labels, any case) to its A-label form using
  // the browser's URL parser, which applies UTS #46. Returns null if it is not valid.
  function domainToAscii(domain) {
    if (!domain || NOT_HOST.test(domain)) return null;
    var host;
    try {
      host = new URL('http://' + domain).hostname;
    } catch (e) {
      return null;
    }
    return isHostname(host) ? host : null;
  }

  // ---- Field checks: each returns { error } or { ascii } ------------------

  function checkName(raw) {
    if (!raw.trim()) return { error: 'Enter your full name.' };
    return {};
  }

  function checkEmail(raw) {
    var value = raw.trim();
    if (!value) return { error: 'Enter your email address.' };
    if (/\s/.test(value)) return { error: 'An email address cannot contain spaces.' };

    var at = value.indexOf('@');
    if (at === -1 || at !== value.lastIndexOf('@')) {
      return { error: 'An email address has exactly one “@”, as in name@example.com.' };
    }
    var local = value.slice(0, at);     // any non-space characters, Unicode included
    var domain = value.slice(at + 1);
    if (!local) return { error: 'Add the part before the “@”.' };
    if (!domain) return { error: 'Add the domain after the “@”, as in name@example.com.' };

    var host = domainToAscii(domain);
    if (!host) return { error: 'The part after the “@” is not a valid domain name.' };

    return { ascii: local + '@' + host };
  }

  function checkWebsite(raw) {
    var value = raw.trim();
    if (!value) return { ascii: '' };   // optional field
    if (/\s/.test(value)) return { error: 'A web address cannot contain spaces.' };

    var hasScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(value);
    var url;
    try {
      url = new URL(hasScheme ? value : 'https://' + value);
    } catch (e) {
      return { error: 'Enter a valid web address, such as https://example.com.' };
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return { error: 'The web address must start with http:// or https://.' };
    }
    if (url.username || url.password) {
      return { error: 'The web address must not contain a user name or password.' };
    }
    // url.hostname is already in A-label form.
    if (!isHostname(url.hostname)) {
      return { error: 'Enter a valid web address, such as https://example.com.' };
    }
    return { ascii: url.href };
  }

  function checkPassword(raw) {
    if (!raw) return { error: 'Choose a password.' };
    if (Array.from(raw).length < 8) return { error: 'Use at least 8 characters.' };
    return {};
  }

  // ---- Wiring -------------------------------------------------------------

  var checks = {
    name: checkName,
    email: checkEmail,
    website: checkWebsite,
    password: checkPassword
  };
  var fieldIds = Object.keys(checks);

  function validateField(id) {
    var input = document.getElementById(id);
    var result = checks[id](input.value);
    var invalid = Boolean(result.error);

    document.getElementById(id + '-error').textContent = result.error || '';
    input.setAttribute('aria-invalid', invalid ? 'true' : 'false');
    input.closest('.field').classList.toggle('invalid', invalid);

    var hidden = document.getElementById(id + '_ascii');
    if (hidden) hidden.value = invalid ? '' : (result.ascii || '');

    return !invalid;
  }

  fieldIds.forEach(function (id) {
    var input = document.getElementById(id);
    input.addEventListener('blur', function () {
      // Don't flag a field the user has merely tabbed through.
      if (input.value || input.getAttribute('aria-invalid') === 'true') validateField(id);
    });
    input.addEventListener('input', function () {
      status.textContent = '';
      // Once a field is marked invalid, clear the error as soon as it is fixed.
      if (input.getAttribute('aria-invalid') === 'true') validateField(id);
    });
  });

  document.getElementById('show-password').addEventListener('change', function (event) {
    document.getElementById('password').type = event.target.checked ? 'text' : 'password';
  });

  form.addEventListener('submit', function (event) {
    status.textContent = '';
    var firstInvalid = null;

    fieldIds.forEach(function (id) {
      if (!validateField(id) && !firstInvalid) firstInvalid = document.getElementById(id);
    });

    if (firstInvalid) {
      event.preventDefault();
      firstInvalid.focus();
      return;
    }

    // All fields are valid. With an action attribute on the form, the browser now
    // submits it normally. Without one (this standalone page), just confirm.
    if (!form.hasAttribute('action')) {
      event.preventDefault();
      status.textContent = 'Everything looks good. Your account can be created.';
    }
  });
})();
</script>
</body>
